__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"CARDS",{enumerable:!0,get:function(){return l}});const l=[{id:'ohm-1827',emoji:'\ud83d\udcdc',category:'Tarih',title:'Ohm Kanunu 1827\u2019de yay\u0131mland\u0131',text:'Alman fizik\xe7i Georg Simon Ohm, ak\u0131m\u0131n gerilimle do\u011fru, diren\xe7le ters orant\u0131l\u0131 oldu\u011funu 1827\u2019de yay\u0131mlad\u0131. \u0130lk ba\u015fta ciddiye al\u0131nmad\u0131; bug\xfcn elektroni\u011fin en temel kural\u0131.'},{id:'volta-pil',emoji:'\ud83d\udd0b',category:'Tarih',title:'\u0130lk pil: Volta s\xfctunu',text:'Alessandro Volta 1800\u2019de \xe7inko ve bak\u0131r diskleri tuzlu suya bat\u0131r\u0131lm\u0131\u015f kartonla \xfcst \xfcste dizerek ilk s\xfcrekli ak\u0131m kayna\u011f\u0131n\u0131 yapt\u0131. Gerilim birimi \u201cvolt\u201d ad\u0131n\u0131 ondan al\u0131r.'},{id:'transistor-1947',emoji:'\ud83d\udd2c',category:'Tarih',title:'Transist\xf6r 1947\u2019de do\u011fdu',text:'Bell Laboratuvarlar\u0131\u2019nda Bardeen, Brattain ve Shockley ilk transist\xf6r\xfc 1947\u2019de \xe7al\u0131\u015ft\u0131rd\u0131. Vakum t\xfcplerinin yerini alarak cep telefonlar\u0131na kadar her \u015feyi m\xfcmk\xfcn k\u0131ld\u0131.'},{id:'ic-1958',emoji:'\ud83e\udde9',category:'Tarih',title:'\u0130lk entegre devre',text:'Jack Kilby 1958\u2019de birka\xe7 komponenti tek bir germanyum par\xe7as\u0131 \xfczerinde birle\u015ftirdi. Bug\xfcn bir telefon i\u015flemcisinde on milyarlarca transist\xf6r bulunur.'},{id:'kirchhoff-1845',emoji:'\ud83d\udd00',category:'Tarih',title:'Kirchhoff yasalar\u0131',text:'Gustav Kirchhoff 1845\u2019te, hen\xfcz \xf6\u011frenciyken, bir d\xfc\u011f\xfcme giren ak\u0131mlar\u0131n toplam\u0131n\u0131n \xe7\u0131kanlara e\u015fit oldu\u011funu ve bir d\xf6ng\xfcdeki gerilimlerin toplam\u0131n\u0131n s\u0131f\u0131r oldu\u011funu g\xf6sterdi.'},{id:'faraday',emoji:'\ud83e\uddf2',category:'Tarih',title:'Faraday ve ind\xfcksiyon',text:'Michael Faraday 1831\u2019de de\u011fi\u015fen manyetik alan\u0131n bir telde gerilim olu\u015fturdu\u011funu ke\u015ffetti. Jenerat\xf6rler, trafolar ve kablosuz \u015farj bu ilkeyle \xe7al\u0131\u015f\u0131r.'},{id:'led-1962',emoji:'\ud83d\udca1',category:'Tarih',title:'G\xf6r\xfcn\xfcr \u0131\u015f\u0131kl\u0131 ilk LED',text:'Nick Holonyak 1962\u2019de k\u0131rm\u0131z\u0131 \u0131\u015f\u0131k veren ilk pratik LED\u2019i yapt\u0131. Mavi LED ise 1990\u2019larda geldi ve beyaz LED ayd\u0131nlatman\u0131n yolunu a\xe7t\u0131; bu bulu\u015f 2014\u2019te Nobel \xf6d\xfcl\xfc ald\u0131.'},{id:'555-zamanlayici',emoji:'\u23f1\ufe0f',category:'Tarih',title:'555 zamanlay\u0131c\u0131',text:'Hans Camenzind\u2019in 1971\u2019de tasarlad\u0131\u011f\u0131 555 entegresi 1972\u2019de piyasaya \xe7\u0131kt\u0131. Yar\u0131m as\u0131rd\u0131r \xfcretiliyor ve her y\u0131l milyarlarca adet sat\u0131ld\u0131\u011f\u0131 tahmin ediliyor.'},{id:'edison-tesla',emoji:'\u26a1',category:'Tarih',title:'Ak\u0131mlar\u0131n sava\u015f\u0131',text:'1880\u2019lerde Edison do\u011fru ak\u0131m\u0131 (DC), Tesla ve Westinghouse alternatif ak\u0131m\u0131 (AC) savundu. AC, trafoyla kolayca y\xfckseltilip uzak mesafeye ta\u015f\u0131nabildi\u011fi i\xe7in \u015febekeyi kazand\u0131.'},{id:'kural-guc',emoji:'\ud83d\udd25',category:'Kural',title:'G\xfc\xe7 her \u015feydir',text:'Bir komponentin harcad\u0131\u011f\u0131 g\xfc\xe7 P = V \xd7 I\u2019d\u0131r. 1/4 W\u2019l\u0131k bir dirence 1 W y\xfcklersen \u0131s\u0131n\u0131r ve yanar. Hesaplad\u0131\u011f\u0131n g\xfcc\xfcn en az iki kat\u0131na dayan\u0131kl\u0131 par\xe7a se\xe7.'},{id:'kural-seri',emoji:'\ud83d\udd17',category:'Kural',title:'Seride ak\u0131m ayn\u0131d\u0131r',text:'Seri ba\u011fl\u0131 komponentlerin hepsinden ayn\u0131 ak\u0131m ge\xe7er, gerilim ise aralar\u0131nda payla\u015f\u0131l\u0131r. Paralel ba\u011flant\u0131da tam tersi: gerilim ayn\u0131, ak\u0131m payla\u015f\u0131l\u0131r.'},{id:'kural-paralel',emoji:'\ud83e\ude9c',category:'Kural',title:'Paralel diren\xe7 k\xfc\xe7\xfcl\xfcr',text:'\u0130ki direnci paralel ba\u011flarsan e\u015fde\u011fer diren\xe7 ikisinin de en k\xfc\xe7\xfc\u011f\xfcnden k\xfc\xe7\xfck olur. \u0130ki e\u015fit diren\xe7 paralelde de\u011ferin yar\u0131s\u0131n\u0131 verir: 1 k\u03a9 \u2225 1 k\u03a9 = 500 \u03a9.'},{id:'kural-kondansator-dc',emoji:'\ud83d\udea7',category:'Kural',title:'Kondansat\xf6r DC\u2019yi durdurur',text:'Kondansat\xf6r dolduktan sonra do\u011fru ak\u0131m ge\xe7irmez, ama de\u011fi\u015fen sinyalleri ge\xe7irir. Bu y\xfczden ses devrelerinde DC\u2019yi engelleyip sesi ge\xe7irmek i\xe7in kullan\u0131l\u0131r.'},{id:'kural-bobin',emoji:'\ud83c\udf00',category:'Kural',title:'Bobin de\u011fi\u015fime direnir',text:'Bobinden ge\xe7en ak\u0131m\u0131 aniden kesersen ters y\xf6nde y\xfcksek bir gerilim s\u0131\xe7ramas\u0131 olu\u015fur. R\xf6le ve motor s\xfcrerken flyback diyodu bu s\u0131\xe7ramay\u0131 g\xfcvenle s\xf6nd\xfcr\xfcr.'},{id:'kural-tau',emoji:'\u23f3',category:'Kural',title:'Be\u015f zaman sabiti',text:'Bir RC devresinde kondansat\xf6r bir \u03c4 (R \xd7 C) s\xfcrede %63, be\u015f \u03c4 s\xfcrede yakla\u015f\u0131k %99 dolar. 10 k\u03a9 ve 100 \xb5F i\xe7in \u03c4 = 1 saniyedir.'},{id:'kural-diyot',emoji:'\u27a1\ufe0f',category:'Kural',title:'Diyotta gerilim d\xfc\u015f\xfcm\xfc',text:'Silisyum diyot iletimdeyken \xfczerinde yakla\u015f\u0131k 0.7 V d\xfc\u015fer, Schottky diyotta bu 0.2\u20130.4 V\u2019tur. Pil ile \xe7al\u0131\u015fan devrelerde bu kay\u0131p \xf6nemli olabilir.'},{id:'kural-transistor',emoji:'\ud83d\udd00',category:'Kural',title:'Transist\xf6r bir musluktur',text:'BJT\u2019de k\xfc\xe7\xfck bir baz ak\u0131m\u0131, kollekt\xf6rden \xe7ok daha b\xfcy\xfck bir ak\u0131m\u0131n ge\xe7mesine izin verir. Kazan\xe7 (hFE) genelde 100 civar\u0131ndad\u0131r: 1 mA baz ak\u0131m\u0131 \u2248 100 mA kollekt\xf6r ak\u0131m\u0131.'},{id:'kural-mosfet',emoji:'\ud83d\udeaa',category:'Kural',title:'MOSFET gerilimle a\xe7\u0131l\u0131r',text:'MOSFET\u2019in kap\u0131s\u0131 ak\u0131m de\u011fil gerilim ister. Mikrodenetleyiciyle s\xfcr\xfcyorsan \u201clogic level\u201d (d\xfc\u015f\xfck e\u015fikli) MOSFET se\xe7; yoksa tam a\xe7\u0131lmaz ve \u0131s\u0131n\u0131r.'},{id:'ipucu-olcum',emoji:'\ud83d\udccf',category:'\u0130pucu',title:'Diren\xe7 \xf6l\xe7meden \xf6nce',text:'Bir direnci devre \xfczerindeyken \xf6l\xe7ersen paralel yollar y\xfcz\xfcnden yanl\u0131\u015f de\u011fer okursun. Do\u011fru \xf6l\xe7\xfcm i\xe7in bir baca\u011f\u0131n\u0131 devreden ay\u0131r ve enerjiyi kes.'},{id:'ipucu-lehim',emoji:'\ud83d\udd27',category:'\u0130pucu',title:'\u0130yi lehim parlakt\u0131r',text:'\u0130yi bir lehim noktas\u0131 parlak ve koni \u015feklindedir. Mat, top gibi duran lehim \u201cso\u011fuk lehim\u201d olabilir; ba\u011flant\u0131 kopabilir. \xd6nce par\xe7ay\u0131 \u0131s\u0131t, sonra lehimi ver.'},{id:'ipucu-breadboard',emoji:'\ud83e\uddf1',category:'\u0130pucu',title:'Breadboard s\u0131n\u0131rlar\u0131',text:'Breadboard kontaklar\u0131 genelde 1 A civar\u0131na kadar dayan\u0131r ve y\xfcksek frekansta ka\xe7ak kapasite olu\u015fturur. Motor ve g\xfc\xe7l\xfc y\xfckler i\xe7in kal\u0131n kablo ve lehimli ba\u011flant\u0131 kullan.'},{id:'ipucu-renk',emoji:'\ud83c\udf08',category:'\u0130pucu',title:'Renk kodunu ezberle',text:'\u201cSiyah, kahve, k\u0131rm\u0131z\u0131, turuncu, sar\u0131, ye\u015fil, mavi, mor, gri, beyaz\u201d 0\u2019dan 9\u2019a kadar rakamlar\u0131 verir. Kendi k\u0131saltman\u0131 uydur; ezber kal\u0131c\u0131 olur.'},{id:'ipucu-gnd',emoji:'\u23da',category:'\u0130pucu',title:'Ortak toprak',text:'Farkl\u0131 kaynaklarla beslenen iki devre birbirine sinyal g\xf6nderiyorsa GND\u2019leri mutlaka birle\u015ftir. Ortak referans olmadan gerilimlerin bir anlam\u0131 kalmaz.'},{id:'ipucu-dekuplaj',emoji:'\ud83d\udee1\ufe0f',category:'\u0130pucu',title:'Dekuplaj kondansat\xf6r\xfc',text:'Her entegrenin besleme baca\u011f\u0131n\u0131n dibine 100 nF seramik kondansat\xf6r koy. Anl\u0131k ak\u0131m ihtiya\xe7lar\u0131n\u0131 kar\u015f\u0131lar, garip s\u0131f\u0131rlanmalar\u0131 ve g\xfcr\xfclt\xfcy\xfc \xf6nler.'},{id:'ipucu-pullup',emoji:'\u2b06\ufe0f',category:'\u0130pucu',title:'Bo\u015fta pin yalan s\xf6yler',text:'Hi\xe7bir yere ba\u011fl\u0131 olmayan bir giri\u015f pini rastgele 0 ve 1 okur. Butonla birlikte 10 k\u03a9 pull-up veya pull-down direnci kullan.'},{id:'ipucu-isinma',emoji:'\ud83c\udf21\ufe0f',category:'\u0130pucu',title:'Parmak testi yerine hesap',text:'Bir reg\xfclat\xf6r\xfcn ne kadar \u0131s\u0131naca\u011f\u0131n\u0131 P = (Vgiri\u015f \u2212 V\xe7\u0131k\u0131\u015f) \xd7 I ile hesapla. 12 V\u2019tan 5 V\u2019a 0.5 A i\xe7in 3.5 W eder; so\u011futucu \u015fartt\u0131r.'},{id:'ipucu-polarite',emoji:'\u2795',category:'\u0130pucu',title:'Ters takma korumas\u0131',text:'Giri\u015fe seri bir diyot (veya P kanall\u0131 MOSFET) koyarsan pil ters tak\u0131ld\u0131\u011f\u0131nda devre korunur. Basit bir \xf6nlem, pahal\u0131 par\xe7alar\u0131 kurtar\u0131r.'},{id:'ipucu-multimetre',emoji:'\ud83e\uddea',category:'\u0130pucu',title:'S\xfcreklilik modu',text:'Multimetrenin bip sesli s\xfcreklilik modu kopuk kablolar\u0131 ve k\u0131sa devreleri saniyeler i\xe7inde bulur. Enerji verilmi\u015f devrede kullanma.'},{id:'bilgi-elektron',emoji:'\u269b\ufe0f',category:'Bilgi',title:'Elektronlar yava\u015f y\xfcr\xfcr',text:'Bir teldeki elektronlar saniyede yaln\u0131z milimetrenin kesirleri kadar ilerler. Lambay\u0131 an\u0131nda yakan \u015fey elektronlar\u0131n kendisi de\u011fil, telde \u0131\u015f\u0131\u011fa yak\u0131n h\u0131zla yay\u0131lan elektrik alan\u0131d\u0131r.'},{id:'bilgi-akim-yonu',emoji:'\u21a9\ufe0f',category:'Bilgi',title:'Ak\u0131m\u0131n y\xf6n\xfc bir anla\u015fmad\u0131r',text:'Devre \u015femalar\u0131nda ak\u0131m art\u0131dan eksiye akar (geleneksel ak\u0131m). Elektronlar ise asl\u0131nda eksiden art\u0131ya hareket eder. Hesaplarda ikisi de ayn\u0131 sonucu verir.'},{id:'bilgi-insan',emoji:'\ud83e\udec0',category:'Bilgi',title:'Tehlikeli olan ak\u0131md\u0131r',text:'V\xfccuttan ge\xe7en 10 mA kas kontrol\xfcn\xfc kaybettirebilir, 50 mA kalbi durdurabilir. Kuru cilt direnci y\xfcksektir ama \u0131slak ciltte \xe7ok d\xfc\u015fer; \u015febeke gerilimi bu y\xfczden \xf6l\xfcmc\xfcld\xfcr.'},{id:'bilgi-sebeke',emoji:'\ud83c\udfe0',category:'Bilgi',title:'Prizdeki 230 V',text:'T\xfcrkiye\u2019de \u015febeke 230 V, 50 Hz\u2019dir. 230 V etkin (RMS) de\u011ferdir; gerilimin tepe de\u011feri yakla\u015f\u0131k 325 V\u2019a ula\u015f\u0131r.'},{id:'bilgi-usb',emoji:'\ud83d\udd0c',category:'Bilgi',title:'USB ne kadar g\xfc\xe7 verir?',text:'Klasik USB 2.0 portu 5 V\u2019ta 500 mA verir. USB-C g\xfc\xe7 da\u011f\u0131t\u0131m\u0131yla (PD) bu 48 V\u2019a ve 240 W\u2019a kadar \xe7\u0131kabilir; cihaz ve \u015farj aleti \xf6nce anla\u015f\u0131r.'},{id:'bilgi-silisyum',emoji:'\ud83e\udea8',category:'Bilgi',title:'Kumdan \xe7ipe',text:'\xc7iplerin hammaddesi silisyum, kumun ana bile\u015fenidir. Safla\u015ft\u0131r\u0131l\u0131p tek kristal h\xe2line getirilen silisyum, ince dilimlere kesilerek \xfczerine devreler bas\u0131l\u0131r.'},{id:'bilgi-pcb',emoji:'\ud83d\udfe9',category:'Bilgi',title:'PCB neden ye\u015fil?',text:'Bask\u0131 devre kartlar\u0131n\u0131n ye\u015fil rengi, bak\u0131r yollar\u0131 koruyan lehim maskesinden gelir. Ye\u015fil geleneksel olarak se\xe7ildi; k\u0131rm\u0131z\u0131, mavi ve siyah kartlar da yayg\u0131n.'},{id:'bilgi-hz',emoji:'\u3030\ufe0f',category:'Bilgi',title:'Hertz nedir?',text:'Hertz saniyedeki tekrar say\u0131s\u0131d\u0131r. 50 Hz \u015febeke saniyede 50 kez y\xf6n de\u011fi\u015ftirir; 16 MHz\u2019lik bir mikrodenetleyici saati saniyede 16 milyon kez t\u0131klar.'},{id:'bilgi-pil-mah',emoji:'\ud83d\udd22',category:'Bilgi',title:'mAh ve Wh fark\u0131',text:'mAh pilin ak\u0131m kapasitesidir, enerjiyi g\xf6stermez. Farkl\u0131 gerilimdeki pilleri kar\u015f\u0131la\u015ft\u0131rmak i\xe7in Wh kullan: 3.7 V \xd7 3 Ah = 11.1 Wh.'}]},811,[]);
